import React from "react";
import { useTranslation } from "react-i18next";
import MainLogo from "../components/MainLogo";
import LiraLine from "../components/LiraLine";
import styles from "../styles/RussianInstruments.module.css";

// Языконезависимые пути к изображениям (порядок соответствует blocks[0..4])
const IMAGES = [
  "/media/gusli.png",
  "/media/domra.png",
  "/media/balalaika.png",
  "/media/bayan.png",
  "/media/bas.png"
];

export default function RussianInstrumentsPage() {
  const { t } = useTranslation();

  // Читаем массив блоков из i18n
  const blocks = t("russianinstruments.blocks", { returnObjects: true });

  return (
    <>
      <MainLogo />
      <h2
        style={{
          color: "gold",
          textAlign: "center",
          fontWeight: "bold",
          fontSize: "2.5rem",
          marginBottom: ".4em",
          letterSpacing: ".04em"
        }}
      >
        {t("russianinstruments.russian_instruments")}
      </h2>
      <LiraLine />

      <div className={styles.page}>
        <main className={styles.container}>
          <div className={styles.instrumentList}>
            {Array.isArray(blocks) &&
              blocks.map((block, index) => (
                <div
                  key={index}
                  className={`unified-block ${styles.instrumentCard} ${
                    index % 2 === 0 ? styles.leftImage : styles.rightImage
                  }`}
                >
                  <div className={styles.imageWrapper}>
                    <img
                      src={IMAGES[index] || "/images/placeholder.png"}
                      alt={block.title}
                    />
                  </div>
                  <div className={`${styles.textWrapper} unified-text`}>
                    <h2>{block.title}</h2>
                    <p style={{ whiteSpace: "pre-line" }}>{block.text}</p>
                  </div>
                </div>
              ))}
          </div>
        </main>
      </div>
    </>
  );
}
