import React, { useEffect, useState } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import './Header.css';

// One shared header for every route. No changes to page content are required.
const NAV = [
  { key: 'home', to: '/' },
  { key: 'choir', children: [{ key: 'chief', to: '/boss' }, { key: 'choir_members', to: '/choir' }] },
  { key: 'concerts', to: '/concert' },
  { key: 'booking', to: '/book' },
  { key: 'media', children: [{ key: 'photo', to: '/media/gallery' }, { key: 'video', to: '/media/video' }, { key: 'press', to: '/media/press' }] },
  { key: 'more', children: [{ key: 'choir_history', to: '/choirhistory' }, { key: 'kossak_history', to: '/kossakhistory' }, { key: 'instruments', to: '/instruments' }] },
  { key: 'map', to: '/map' },
];
const LANGUAGES = ['en', 'de', 'fr', 'nl', 'it'];

export default function Header() {
  const { t, i18n } = useTranslation();
  const location = useLocation();
  const [open, setOpen] = useState(false);
  const [expanded, setExpanded] = useState('');
  const [languageOpen, setLanguageOpen] = useState(false);

  useEffect(() => { setOpen(false); setExpanded(''); setLanguageOpen(false); }, [location.pathname]);
  useEffect(() => {
    if (!open) return undefined;
    const closeOnEscape = (event) => { if (event.key === 'Escape') setOpen(false); };
    window.addEventListener('keydown', closeOnEscape);
    const previous = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { window.removeEventListener('keydown', closeOnEscape); document.body.style.overflow = previous; };
  }, [open]);

  const label = (key) => t(`header.nav.${key}`);
  const close = () => setOpen(false);
  const renderItems = (variant) => NAV.map((item) => {
    if (item.to) return <li key={item.key}><NavLink end={item.to === '/'} to={item.to} onClick={close}>{label(item.key)}</NavLink></li>;
    const active = expanded === `${variant}-${item.key}`;
    return <li key={item.key} className="dk-nav-group">
      <button type="button" aria-expanded={active} onClick={() => setExpanded(active ? '' : `${variant}-${item.key}`)}>
        {label(item.key)} <span className="dk-chevron" aria-hidden="true">⌄</span>
      </button>
      <ul className={`dk-subnav${active ? ' dk-visible' : ''}`}>
        {item.children.map((child) => <li key={child.key}><NavLink to={child.to} onClick={close}>{label(child.key)}</NavLink></li>)}
      </ul>
    </li>;
  });

  return <header className="dk-header">
    <div className="dk-header-bar">
      <NavLink className="dk-brand" to="/" onClick={close} aria-label="Don Kosaken Chor — Home">
        <img src="/media/logo.png" alt="" /> <span>DON KOSAKENCHOR</span>
      </NavLink>
      <nav className="dk-desktop-nav" aria-label="Main navigation"><ul>{renderItems('desktop')}</ul></nav>
      <div className="dk-desktop-lang">
        <button type="button" onClick={() => setLanguageOpen((value) => !value)} aria-expanded={languageOpen}>{i18n.language.split('-')[0].toUpperCase()} <span aria-hidden="true">⌄</span></button>
        {languageOpen && <div className="dk-language-options">{LANGUAGES.map((code) => <button key={code} onClick={() => { i18n.changeLanguage(code); setLanguageOpen(false); }}>{code.toUpperCase()}</button>)}</div>}
      </div>
      <button type="button" className={`dk-toggle${open ? ' dk-active' : ''}`} onClick={() => setOpen(!open)} aria-label={open ? 'Close menu' : 'Open menu'} aria-expanded={open} aria-controls="dk-drawer">
        <span></span><span></span><span></span>
      </button>
    </div>

    <div id="dk-drawer" className={`dk-drawer${open ? ' dk-open' : ''}`} aria-hidden={!open}>
      <button className="dk-backdrop" tabIndex={open ? 0 : -1} aria-label="Close menu" onClick={close} />
      <div className="dk-door dk-door-left">
        <div className="dk-door-heading">MENU</div>
        <nav aria-label="Mobile navigation"><ul className="dk-mobile-links">{renderItems('mobile')}</ul></nav>
        <div className="dk-mobile-languages" aria-label="Language">{LANGUAGES.map((code) => <button key={code} className={i18n.language.startsWith(code) ? 'dk-current' : ''} onClick={() => i18n.changeLanguage(code)}>{code.toUpperCase()}</button>)}</div>
      </div>
      <div className="dk-door dk-door-right">
        <div className="dk-door-logo"><NavLink to="/" onClick={close}><img src="/media/logo.png" alt="Don Kosaken Chor" /><span>DON KOSAKENCHOR</span></NavLink></div>
        <div className="dk-door-social"><span className="dk-social-title">SOCIAL</span><div className="dk-social-links">
          {/* Replace these generic service URLs with official choir profiles when available. */}
          <a href="https://facebook.com/" target="_blank" rel="noopener noreferrer" aria-label="Facebook">Facebook</a>
          <a href="https://youtube.com/" target="_blank" rel="noopener noreferrer" aria-label="YouTube">YouTube</a>
        </div></div>
      </div>
    </div>
  </header>;
}
