import React from "react";
import { useTranslation } from "react-i18next";
import styles from "../styles/CossackHistory.module.css";
import LiraLine from "../components/LiraLine";
import MainLogo from "../components/MainLogo";

const IMAGES = ["/images/8.png","/images/9.png","/images/10.png","/images/11.png","/images/12.png"];

export default function KossakHistoryPage() {
  const { t } = useTranslation();
  // read whole blocks array from i18n JSON
  const blocks = t("kossakhistory.blocks", { returnObjects: true });

  return (
    <>
      <MainLogo />
      <h2 style={{color: "gold", textAlign: "center", fontWeight: "bold", fontSize: "2.5rem", marginBottom: ".4em", letterSpacing: ".04em"}}>
        {t("kossakhistory.history_of_cosacks")}
      </h2>
      <LiraLine />

      <div className={styles.wrapper}>
        {Array.isArray(blocks) && blocks.map((block, i) => (
          <div className={`${styles.block} ${i % 2 === 0 ? styles.normal : styles.reverse} unified-block`} key={i}>
            <div className={styles.image}>
              <img src={IMAGES[i] || "/images/placeholder.png"} alt={block.title} />
            </div>
            <div className={`${styles.text} unified-text`}>
              <h2>{block.title}</h2>
              <p style={{whiteSpace:"pre-line"}}>{block.text}</p>
            </div>
          </div>
        ))}
      </div>
    </>
  );
}
