import React from "react";
import { Link } from "react-router-dom";
import "../styles/gallery.css";
import LiraLine from "../components/LiraLine";
import MainLogo from "../components/MainLogo";

const albums = [
  { slug: "volume-1", title: "Tour 2016", cover: "/Gallery/volume-1/1.jpg" },
  { slug: "volume-2", title: "Tour 2018", cover: "/Gallery/volume-2/1.jpg" },
  { slug: "volume-3", title: "Marcell", cover: "/Gallery/volume-3/1.jpg" },
  { slug: "volume-4", title: "Posters", cover: "/Gallery/volume-4/1.jpg" },
];

export default function GalleryHub() {
  return (
    <div className="gallery-page">
      <MainLogo />
              <h2 style={{color: "gold", textAlign: "center", fontWeight: "bold", fontSize: "2.5rem", marginBottom: ".4em", letterSpacing: ".04em"}}>
                GALLERY
              </h2>
              <LiraLine />
      
      <div className="gallery-container">
        <div className="gallery-hub__grid">
          {albums.map((a) => (
            <Link key={a.slug} to={`/gallery/${a.slug}`} className="album-tile" aria-label={`Open ${a.title}`}>
              <img className="album-tile__img" src={a.cover} alt={a.title} loading="lazy" />
              <div className="album-tile__fade" />
              <h3 className="album-tile__title">{a.title}</h3>
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
}
