// PhilharmonicMap.jsx
import React from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

// Фикс иконок Leaflet для сборщиков (Vite/CRA)
import iconUrl from "leaflet/dist/images/marker-icon.png";
import iconRetinaUrl from "leaflet/dist/images/marker-icon-2x.png";
import shadowUrl from "leaflet/dist/images/marker-shadow.png";
L.Icon.Default.mergeOptions({ iconRetinaUrl, iconUrl, shadowUrl });

// Данные (фото берём из public/images/map/{n}.jpeg)
const locations = [
  { id: 1, name: "Берлинская филармония", date: "2024-05-12", coords: [52.5146, 13.3501] },
  { id: 2, name: "Гамбургская филармония", date: "2024-06-03", coords: [53.5585, 9.9876] },
  { id: 3, name: "Дрезденская филармония", date: "2024-07-18", coords: [51.0504, 13.7373] },
  { id: 4, name: "Кёльнская филармония", date: "2024-08-25", coords: [50.9375, 6.9603] },
  // при необходимости добавьте 5,6
];

export default function PhilharmonicMap() {
  return (
    <div style={{ height: "80vh", width: "100%", marginTop: 40 }}>
      <MapContainer
        center={[52.5, 13.3]}
        zoom={6}
        scrollWheelZoom
        style={{ height: "100%", width: "100%" }}
      >
        <TileLayer
          attribution='&copy; OpenStreetMap contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {locations.map((loc, idx) => {
          const photo = `/images/map/${loc.id ?? idx + 1}.jpg`; // из public
          return (
            <Marker position={loc.coords} key={loc.id ?? idx}>
              <Popup closeButton={true}>
                <div className="popup-card">
                  <div className="popup-thumb">
                    <img src={photo} alt={loc.name} />
                  </div>
                  <div className="popup-meta">
                    <div className="popup-title">{loc.name}</div>
                    <div className="popup-date">{loc.date}</div>
                  </div>
                </div>
              </Popup>
            </Marker>
          );
        })}
      </MapContainer>

      {/* Локальные стили попапа (можете вынести в CSS) */}
      <style>{`
        .leaflet-popup-content { margin: 8px 12px; }
        .popup-card { display: flex; align-items: center; gap: 10px; min-width: 220px;background: #ffe77aff; }
        .popup-thumb { flex: 0 0 auto; width: 172px; height:172px; border-radius: 8px; overflow: hidden; border: 1px solid rgba(0,0,0,.15); }
        .popup-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
        .popup-meta { display: grid; gap: 4px; }
        .popup-title { font-weight: 700; line-height: 1.2; }
        .popup-date { font-size: 16px; opacity: .7; }
      `}</style>
    </div>
  );
}
