import React from 'react';
import { Link } from 'react-router-dom';
import LeraLogo from '../components/images/Lera.png';

/**
 * Декоративный SVG-переход с двумя линиями и логотипом Леры посередине.
 * Логотип перекрывает пересечение двух линий.
 * Используется как React Router Link для навигации.
 *
 * Props:
 * - to: путь для React Router Link
 * - logoSize (optional): размер логотипа в пикселях (width=height). По умолчанию 30.
 * - lineColor (optional): цвет линий. По умолчанию золотой (#FFD700).
 * - lineThickness (optional): толщина линий в пикселях. По умолчанию 2.
 */
const DecorativeTransition = ({ to, logoSize = 40, lineColor = '#FFD700', lineThickness = 2 }) => {
  const halfSize = logoSize / 2;
  const svgHeight = logoSize;
  const centerY = svgHeight / 2;

  return (
    <Link to={to} style={{ display: 'block', textDecoration: 'none' }}>
      <svg
        width="100%"
        height={svgHeight}
        xmlns="http://www.w3.org/2000/svg"
        style={{ verticalAlign: 'middle' , marginBottom:"1vh"}}
      >
        {/* Левая линия */}
        <line
          x1="0"
          y1={centerY}
          x2="49%"
          y2={centerY}
          stroke={lineColor}
          strokeWidth={lineThickness}
        />
        {/* Правая линия */}
        <line
          x1="51%"
          y1={centerY}
          x2="100%"
          y2={centerY}
          stroke={lineColor}
          strokeWidth={lineThickness}
        />
        {/* Логотип Леры по центру */}
        <image
          href={LeraLogo}
          x="50%"
          y="0"
          width={logoSize}
          height={logoSize}
          transform={`translate(${-halfSize}, 0)`}
        />
      </svg>
    </Link>
  );
};

export default DecorativeTransition;
