import React from "react";
import { useTranslation } from "react-i18next";
import LiraLine from "../components/LiraLine";
import MainLogo from "../components/MainLogo";

export default function ConcertsPage() {
  const { t } = useTranslation();

  return (
    <>
      <MainLogo />
      <h2
        style={{
          color: "gold",
          textAlign: "center",
          fontWeight: "bold",
          fontSize: "2.5rem",
          marginBottom: ".4em",
          letterSpacing: ".04em",
        }}
      >
        {t("concerts.title")}
      </h2>
      <LiraLine />

      <div
        style={{
          maxWidth: "70vw",
          margin: "0 auto",
          padding: "2.2em 2vw 2em 2vw",
        }}
      >
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: "2em",
            alignItems: "flex-start",
          }}
        >
          <img
            src="/media/3.jpg"
            alt={t("concerts.image_alt_marcel")}
            style={{
              width: "100%",
              maxWidth: "27vw",
              borderRadius: "1em",
              objectFit: "cover",
              boxShadow: "0 3px 18px #ffd70036",
            }}
          />
          <div style={{ flex: "1 1 340px", minWidth: 280, color: "var(--gold-main)" }}>
            <p style={{ fontSize: "1.5em", marginTop: "9vh", lineHeight: "1.7" }}>
              {t("concerts.covid_message")}
              <br />
              <br />
              {t("concerts.signoff")}
              <br />
              {t("concerts.signature")}
            </p>
          </div>
        </div>
      </div>
    </>
  );
}
