// ===== ВСПОМОГАТЕЛЬНОЕ ПРЕДСТАВЛЕНИЕ ОДНОЙ СТАТЬИ =====
function ArticleView({ article }) {
  if (!article) return <div style={{ padding: "2rem", color: "var(--gold-main)" }}>Статья не найдена.</div>;
  return (
    <div style={{ maxWidth: 980, margin: "0 auto 1.2em auto" }}>
      <div style={{ color: "var(--gold-main)", margin: "1.2rem 0" }}>
        <h1 style={{ fontSize: "2rem", margin: 0 }}>{article.title}</h1>
        <div style={{ opacity: 0.8, marginTop: ".3rem" }}>
          {article.date} {article.author ? `• ${article.author}` : null}
        </div>
      </div>
      {article.img && (
        <img
          src={article.img}
          alt={article.title}
          style={{ width: "100%", borderRadius: "1rem", border: "2px solid var(--gold-main)" }}
        />
      )}
      <div style={{ color: "var(--gold-main)", fontSize: "1.05rem", lineHeight: 1.6, marginTop: "1rem" }}>
        {article.content.map((p, i) => (
          <p key={i} style={{ margin: "0 0 1em 0" }}>{p}</p>
        ))}
      </div>
    </div>
  );
}

// ===== ОДИН КОМПОНЕНТ С ТРЕМЯ «ЛИСТАМИ» =====
// Лист 1 — список (3 блока);
// Лист 2/3/4 — детальные страницы (переключение внутри компонента, без роутера).
export default function PressSingle() {
  const [view, setView] = React.useState({ mode: "list", slug: null });

  const open = (slug) => setView({ mode: "detail", slug });
  const back = () => setView({ mode: "list", slug: null });

  if (view.mode === "detail") {
    const idx = Math.max(0, PRESS.findIndex((a) => a.slug === view.slug));
    const article = PRESS[idx];
    const prev = () => setView({ mode: "detail", slug: PRESS[(idx - 1 + PRESS.length) % PRESS.length].slug });
    const next = () => setView({ mode: "detail", slug: PRESS[(idx + 1) % PRESS.length].slug });

    return (
      <>
        <MainLogo />
        <ArticleView article={article} />
        <div style={{ maxWidth: 980, margin: "0 auto 2.2em auto", display: "flex", gap: "0.6rem", justifyContent: "space-between" }}>
          <button onClick={prev} style={btn}>← Предыдущая</button>
          <button onClick={back} style={btn}>К списку</button>
          <button onClick={next} style={btn}>Следующая →</button>
        </div>
        <KeyLine />
      </>
    );
  }

  // Список (лист 1)
  return (
    <>
      <MainLogo />
      <h2
        style={{
          color: "gold",
          textAlign: "center",
          fontWeight: "bold",
          fontSize: "2.5rem",
          marginBottom: ".4em",
          letterSpacing: ".04em",
        }}
      >
        PRESS
      </h2>
      <LiraLine />

      <div
        style={{
          maxWidth: "980px",
          margin: "0 auto 3em auto",
          display: "flex",
          flexDirection: "column",
          gap: "1.6em",
        }}
      >
        {PRESS.map((p) => (
          <div
            key={p.slug}
            style={{
              display: "flex",
              flexDirection: "row",
              borderRadius: "1.2em",
              border: "2px solid var(--gold-main)",
              overflow: "hidden",
              minHeight: 180,
            }}
          >
            {p.img && (
              <div style={{ flex: "0 0 220px", background: "#181e3d" }}>
                <img
                  src={p.img}
                  alt={p.title}
                  style={{ width: 220, height: "100%", objectFit: "cover", display: "block" }}
                />
              </div>
            )}
            <div
              style={{
                flex: "1 1 0%",
                padding: "1.4em 1.6em",
                color: "var(--gold-main)",
                display: "flex",
                flexDirection: "column",
                justifyContent: "center",
              }}
            >
              <div style={{ fontWeight: 700, fontSize: "1.18em", marginBottom: ".4em" }}>{p.title}</div>
              <div style={{ opacity: 0.8, marginBottom: ".6em" }}>{p.date} {p.author ? `• ${p.author}` : null}</div>
              <div style={{ marginBottom: ".7em", fontSize: "1.05em" }}>{p.excerpt}</div>
              <div>
                <button onClick={() => open(p.slug)} style={linkBtn}>
                  Подробнее →
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </>
  );
}

