import React from "react";
import { useTranslation } from "react-i18next";
import LiraLine from "../components/LiraLine";
import MainLogo from "../components/MainLogo";
import styles from "../styles/CossackHistory.module.css";

// изображения для блоков по порядку (0..2)
const IMAGES = ["/media/7.png", "/media/4.jpg", "/media/1.jpg"];

export default function ChoirHistoryPage() {
  const { t } = useTranslation();

  // читаем массив блоков (title/text) из i18n
  const blocks = t("choirhistory.blocks", { returnObjects: true });

  return (
    <>
      <MainLogo />
      <h2
        style={{
          color: "gold",
          textAlign: "center",
          fontWeight: "bold",
          fontSize: "2.5rem",
          marginBottom: ".4em",
          letterSpacing: ".04em",
        }}
      >
        {t("choirhistory.history_of_choir")}
      </h2>
      <LiraLine />

      <div className={styles.wrapper}>
        {Array.isArray(blocks) &&
          blocks.map((block, i) => (
            <div
              key={i}
              className={`${styles.block} ${
                i % 2 === 0 ? styles.normal : styles.reverse
              } unified-block`}
            >
              <div className={styles.image}>
                <img
                  src={IMAGES[i] || "/images/placeholder.png"}
                  alt={block.title}
                />
              </div>
              <div className={`${styles.text} unified-text`}>
                <h2>{block.title}</h2>
                <p style={{ whiteSpace: "pre-line" }}>{block.text}</p>
              </div>
            </div>
          ))}
      </div>
    </>
  );
}
