import { motion, AnimatePresence } from "framer-motion";
import { useState, useEffect } from "react";

const phrases = [
  "Connected Heart",
  "Connected Soul",
  "Connected People"
];

export default function AnimatedText() {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setIndex((prev) => (prev + 1) % phrases.length);
    }, 5000); // каждые 3 секунды меняем фразу
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="relative w-full  flex items-center justify-center py-10  ">
      <AnimatePresence mode="wait">
        <motion.h1
          key={phrases[index]}
          initial={{ opacity: 0, filter: "blur(20px)", clipPath: "inset(0 100% 0 0)" }}
          animate={{ opacity: 1, filter: "blur(0px)", clipPath: "inset(0 0% 0 0)" }}
          exit={{ opacity: 0, filter: "blur(20px)", clipPath: "inset(0 0% 0 100%)" }}
          transition={{ duration: 2, ease: "easeInOut" }}
          className="text-5xl font-extrabold text-transparent bg-gradient-to-r from-yellow-300 via-orange-400 to-yellow-500 bg-clip-text"
        >
          {phrases[index]}
        </motion.h1>
      </AnimatePresence>

      <style jsx>{`

        .bg-animated {
          background: linear-gradient(270deg, #ffcc00, #ff9900, #ff6600);
          background-size: 600% 600%;
          animation: gradientMove 10s ease infinite;
        }
        @keyframes gradientMove {
          0% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }

        
      `}</style>
    </div>
  );
}
