import { Canvas, useFrame, useLoader } from "@react-three/fiber";
import { Text } from "@react-three/drei";
import * as THREE from "three";
import { useRef } from "react";

// === Глобус с текстурой ===
function Globe() {
  const texture = useLoader(THREE.TextureLoader, "/textures/globe.png");

  // чтобы текстура повторялась
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;

  // уменьшаем "масштаб" — повторяем картинку несколько раз
  texture.repeat.set(2,3); // здесь "5" значит в 5 раз мельче

  const globeRef = useRef();

  useFrame(() => {
    if (globeRef.current) {
      globeRef.current.rotation.y += 0.002;
    }
  });

  return (
    <mesh ref={globeRef}>
      <sphereGeometry args={[2, 64, 64]} />
      <meshStandardMaterial map={texture} />
    </mesh>
  );
}

// === Текст вокруг экватора ===
function OrbitingPhrase({ phrase, radius = 2.6 }) {
  const groupRef = useRef();
  const chars = phrase.split("");

  useFrame(({ clock }) => {
    if (groupRef.current) {
      const t = clock.getElapsedTime();
      groupRef.current.rotation.y = -t * 0.2; // текст влево →→→
    }
  });

  return (
    <group ref={groupRef}>
      {chars.map((char, i) => {
        const angle = (i / chars.length) * Math.PI * 2;
        const x = Math.cos(angle) * radius;
        const z = Math.sin(angle) * radius;
        return (
          <Text
            key={i}
            position={[x, 0, z]}
            // буквы лицом к зрителю
            rotation={[0, -angle + Math.PI / 2, 0]}
            fontSize={0.45}
            color="gold"
            anchorX="center"
            anchorY="middle"
            font="/fonts/Merriweather-Bold.ttf"
          >
            {char}
          </Text>
        );
      })}
    </group>
  );
}

export default function Hero3D() {
  return (
    <div style={{ width: "100%", height: "100vh"  }}>
      <Canvas camera={{ position: [0, 0, 7], fov: 50 }}>
        <ambientLight intensity={0.6} />
        <directionalLight position={[5, 5, 5]} intensity={1} />

        <Globe />
        <OrbitingPhrase phrase="  ffeoherV .N lecraM rotcudnoc-feihC ROHCNEKASOK NOD" />
      </Canvas>
    </div>
  );
}
