// GalleryViewer.jsx
import React, { useMemo, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useTranslation } from "react-i18next";
import styles from "../styles/CossackHistory.module.css";
import LiraLine from "../components/LiraLine";
import MainLogo from "../components/MainLogo";

// ===== Структурированный список альбомов =====
const albumImages = {
  "volume-1": [
    "/gallery/volume-1/1.jpg",
    "/gallery/volume-1/2.jpg",
    "/gallery/volume-1/3.jpg",
    "/gallery/volume-1/4.jpg",
    "/gallery/volume-1/5.jpg",
    "/gallery/volume-1/6.jpg",
  ],
  "volume-2": [
    "/gallery/volume-2/1.jpg",
    "/gallery/volume-2/2.jpg",
    "/gallery/volume-2/3.jpg",
    "/gallery/volume-2/4.jpg",
    "/gallery/volume-2/5.jpg",
    "/gallery/volume-2/6.jpg",
  ],
  "volume-3": [
    "/gallery/volume-3/1.jpg",
    "/gallery/volume-3/2.jpg",
    "/gallery/volume-3/3.jpg",
    "/gallery/volume-3/4.jpg",
    "/gallery/volume-3/5.jpg",
    "/gallery/volume-3/6.jpg",
  ],
  "volume-4": [
    "/gallery/volume-4/1.jpg",
    "/gallery/volume-4/2.jpg",  
    "/gallery/volume-4/3.jpg",
    "/gallery/volume-4/4.jpg",
    "/gallery/volume-4/5.jpg",
    "/gallery/volume-4/6.jpg",
  ],
};

const albumTitles = {
  "volume-1": "Tour 2016",
  "volume-2": "Tour 2018",
  "volume-3": "Marcell ",
  "volume-4": "Posters",
};

export default function GalleryViewer() {
  const { album = "" } = useParams();
  const navigate = useNavigate();
  const urls = albumImages[album] || [];
  const [idx, setIdx] = useState(0);

  const title = useMemo(
    () => albumTitles[album] || album.toUpperCase(),
    [album]
  );

  function next() {
    if (!urls.length) return;
    setIdx((i) => (i + 1) % urls.length);
  }
  function prev() {
    if (!urls.length) return;
    setIdx((i) => (i - 1 + urls.length) % urls.length);
  }
  function go(i) {
    setIdx(i);
  }

  if (!urls.length) {
    return (
      
       
      <div className="gallery-page">
      <MainLogo />
              <h2 style={{color: "gold", textAlign: "center", fontWeight: "bold", fontSize: "2.5rem", marginBottom: ".4em", letterSpacing: ".04em"}}>
                GALLERY
              </h2>
              <LiraLine />
      
        <div className="gallery-container">
          <div className="viewer__head">
            <h1 className="viewer__title">{title}</h1>
            <button onClick={() => navigate(-1)} className="viewer__back">
              ← Back to gallery
            </button>
          </div>
          <div className="empty">
            Нет изображений для альбома <b>{album}</b>
          </div>
        </div>
      </div>
     
    );
  }

  return (
    <div className="gallery-page">
      
         <MainLogo />
              <h2 style={{color: "gold", textAlign: "center", fontWeight: "bold", fontSize: "2.5rem", marginBottom: ".4em", letterSpacing: ".04em"}}>
                GALLERY
              </h2>
              <LiraLine />
      
      <div className="gallery-container">
        <div className="viewer__head">
          <h1 className="viewer__title">{title}</h1>
          <button onClick={() => navigate(-1)} className="viewer__back">
            ← Back to gallery
          </button>
        </div>

        <div className="viewer">
          <div className="viewer__stage">
            <button
              className="viewer__nav viewer__nav--prev"
              onClick={prev}
              aria-label="Previous"
            >
              ‹
            </button>
            <img className="viewer__img"            src={urls[idx]}
              alt={`${title} — ${idx + 1}`}           onClick={next}
            />
            <button
              className="viewer__nav viewer__nav--next"
              onClick={next}
              aria-label="Next"
            >
              ›
            </button>
          </div>

          <div className="thumbs" role="listbox" aria-label="Thumbnails">
            {urls.map((u, i) => (
              <button
                key={u}
                className={`thumbs__btn ${
                  i === idx ? "thumbs__btn--active" : ""
                }`}
                onClick={() => go(i)}
                aria-label={`Open ${i + 1}`}
              >
                <img
                  className="thumbs__img"
                  src={u}
                  alt={`Thumb ${i + 1}`}
                  loading="lazy"
                />
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
