import React from 'react';
import { Link } from 'react-router-dom';
import KeyLogo from './images/key.png'; // скорректируйте путь под ваш проект

/**
 * Декоративный SVG-переход с двумя линиями и логотипом по центру.
 */
const DecorativeTransitionKey = ({
  to,
  logoSize = 40,
  lineColor = '#FFD700',
  lineThickness = 1.5,
}) => {
  const half = logoSize / 2;
  const centerY = logoSize / 2;

  return (
    <Link to={to} style={{ display: 'block', textDecoration: 'none' }}>
      <div style={{ position: 'relative', width: '100%', height: logoSize }}>
        {/* Линии */}
        <svg
          width="100%"
          height={logoSize}
          xmlns="http://www.w3.org/2000/svg"
          style={{ position: 'absolute', top: 0, left: 0 }}
        >
          <line
            x1="0"
            y1={centerY}
            x2="48%"
            y2={centerY}
            stroke={lineColor}
            strokeWidth={lineThickness}
          />
          <line
            x1="52%"
            y1={centerY}
            x2="100%"
            y2={centerY}
            stroke={lineColor}
            strokeWidth={lineThickness}
          />
        </svg>

        {/* Логотип поверх */}
        <img
          src={KeyLogo}
          alt="Key Logo"
          style={{
            position: 'absolute',
            top: 0,
            left: '50%',
            width: logoSize,
            height: logoSize,
            transform: `translate(-${half}px, 0)`,
          }}
        />
      </div>
    </Link>
  );
};

export default DecorativeTransitionKey;
