import React from "react";
import { useTranslation } from "react-i18next";
import LiraLine from "../components/LiraLine";
import "../styles/BossPage.css";

export default function BossPage() {
  const { t } = useTranslation();

  const HERO_IMG = t("boss.hero_img"); // или оставьте константой, если путь фиксированный
  const blocks = t("boss.blocks", { returnObjects: true }); // вернёт массив объектов {title, text}

  return (
    <div className="boss-page">
      <figure className="boss-hero">
        <img src={HERO_IMG} alt={t("boss.hero_alt")} />
      </figure>
      <h1 className="boss-title">{t("boss.page_title")}</h1>
      <LiraLine />
      <div className="boss-wrapper">
        {blocks.map((b, i) => (
          <section key={i} className="boss-block">
            {b.title && <h3 className="boss-heading">{b.title}</h3>}
            <p className="boss-text">{b.text}</p>
          </section>
        ))}
      </div>
      <LiraLine />
    </div>
  );
}
