import React from 'react';
import { NavLink } from 'react-router-dom';

const cards = [
  {
    id: 1,
    image: '/media/1.jpeg',
    logo: '/media/logo.png',
    title: 'Chief-conductor',
    to: '/boss',        // внутренняя страница ChiefConductor
  },
  {
    id: 2,
    image: '/media/2.jpg',
    logo: '/media/logo.png',
    title: 'Musicians',
    to: '/choir',       // внутренняя страница Musicians
  },
];

export default function NewsCards() {
  return (
    <div className="mx-auto py-8">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {cards.map((card) => (
          <div
            key={card.id}
            className="flex flex-col items-center border border-gold text-gold uppercase p-4"
          >
            <img
              src={card.image}
              alt={card.title}
              className="w-full h-88 object-cover mb-4"
            />
            <img
              src={card.logo}
              alt="Logo"
              className="w-16 h-16 object-contain mb-4"
            />
            <h3 className="text-lg font-bold mb-4">{card.title}</h3>

            <NavLink
              to={card.to}
              className="px-4 py-2 border border-gold rounded uppercase"
            >
              More
            </NavLink>
          </div>
        ))}
      </div>
    </div>
  );
}
