import React from "react";
import { useTranslation } from "react-i18next";
import MainLogo from "../components/MainLogo";
import LiraLine from "../components/LiraLine";
import styles from "../styles/CossackHistory.module.css";

const blocks = [
  {
    title: "Vocalists",
    image: "/images/2.jpg",
    text: "Every voice in the Don KosakenChor is professionally trained. Many of the singers serve as soloists in leading opera houses throughout Eastern Europe. Rooted in the rich vocal traditions of their culture, they bring depth, power and authenticity to every performance.\n\nWhat sets this choir apart is the artistry of Marcel N. Verhoeff, whose ability to unite individual soloists into one harmonious sound gives the ensemble its unmistakable identity. It is a sound born from tradition, shaped by excellence and lifted by a shared love for music."
  },
  {
    title: "The Ensemble",
    image: "/media/23.jpg",
    text: "The Instrumental Soloists Ensemble Philharmonia forms the musical heart of our collaboration with the renowned Don KosakenChor and chief conductor Marcel N. Verhoeff. Nearly all members have worked with Verhoeff for over 30 years, forged during their time with the Moscow Festival Ensemble.\n\nValery Elchik, a close friend and artistic partner of Marcel N. Verhoeff, played a vital role in shaping the ensemble’s sound. A master arranger, Elchik’s legacy lives on in the ensemble’s unique character and artistic depth."
  }
];

export default function EnsemblePage() {
  const { t } = useTranslation();

  return (
    <>
      <MainLogo />
      <h2
        style={{
          color: "gold",
          textAlign: "center",
          fontWeight: "bold",
          fontSize: "2.5rem",
          marginBottom: ".4em",
          letterSpacing: ".04em",
        }}
      >
        {t("ensemble.choir_and_ensemble")}
      </h2>
      <LiraLine />
      <div className={styles.wrapper}>
        {blocks.map((block, i) => (
          <div
            key={i}
            className={`${styles.block} ${i % 2 === 0 ? styles.normal : styles.reverse} unified-block`}
          >
            <div className={styles.image}>
              <img src={block.image} alt={block.title} />
            </div>
            <div className={`${styles.text} unified-text`}>
              <h2>{t(`ensemble.block${i + 1}_title`)}</h2>
              <p>{t(`ensemble.block${i + 1}_text`)}</p>
            </div>
          </div>
        ))}
      </div>
    </>
  );
}
