import React from "react";
import MainLogo from "../components/MainLogo";

import LiraLine from "../components/LiraLine";
import KeyLine from "../components/KeyLine";

// Массив видео — добавляй новые блоки по аналогии!
const VIDEOS = [
  // YouTube (через iframe)
    // Локальный mp4 (скачанный и лежит в public/videos)
  {
    type: "mp4",
    title: "Concert Highlights 2024",
    src: "/videos/1.mp4"
  }
];

export default function VideoPage() {
  return (
    <>
      
      <MainLogo />
      <h2 style={{
        color: "gold", textAlign: "center", fontWeight: "bold",
        fontSize: "2.5rem", marginBottom: ".4em", letterSpacing: ".04em"
      }}>
     
        VIDEO
      </h2>
     <LiraLine />
      {/* Центральный VIP-блок с видео */}
      <div style={{
        maxWidth: "920px",
        margin: "0 auto 2.8em auto",
        background: "",
        borderRadius: "1.2em",
        border: "2.5px solid var(--gold-main)",
        
        padding: "2.5em 2vw 2.7em 2vw",
        color: "var(--gold-main)"
      }}>
        {VIDEOS.map((vid, idx) => (
          <div key={vid.src} style={{
            marginBottom: idx < VIDEOS.length - 1 ? "2.4em" : 0
          }}>
            <div style={{
              color: "gold",
              fontWeight: 600,
              textAlign: "center",
              fontSize: "1.16em",
              marginBottom: "1em",
              letterSpacing: ".01em"
            }}>{vid.title}</div>
            <div style={{
              display: "flex",
              justifyContent: "center",
              background: "#181e3d",
              borderRadius: "1em",
              boxShadow: "0 2px 16px #ffd70028",
              border: "1.5px solid var(--gold-main)",
              padding: "1em"
            }}>
              {vid.type === "youtube" ? (
                <iframe
                  src={vid.src}
                  width="100%"
                  height="370"
                  title={vid.title}
                  frameBorder="0"
                  allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                  style={{
                    borderRadius: "1em",
                    maxWidth: "680px",
                    width: "100%",
                    background: "#111"
                  }}
                />
              ) : (
                <video
                  controls
                  width="100%"
                  style={{
                    borderRadius: "1em",
                    maxWidth: "680px",
                    background: "#000"
                  }}
                >
                  <source src={vid.src} type="video/mp4" />
                  Ваш браузер не поддерживает видео.
                </video>
              )}
            </div>
          </div>
        ))}
      </div>
      
    </>
  );
}
