import React from "react";
import MainLogo from "../components/MainLogo";
import LiraLine from "../components/LiraLine";

import "../styles/legalPages.css";

export default function CookieSettingsPage() {
  return (
    <>
      <MainLogo />
  
      <h2 className="legal-heading">COOKIE SETTINGS</h2>
 <LiraLine />

      <div className="legal-container">
        <h2 className="legal-subheading">About Cookies</h2>
        <p>
          Our website uses only essential, functional, and non-intrusive analytical cookies to ensure the site functions properly and to improve user experience.
          <br /><br />These cookies:
        </p>
        <ul>
          <li>Remember your settings and preferences</li>
          <li>Help us understand how the website is used</li>
        </ul>
        <p>
          You can disable or delete cookies via your browser settings at any time.
          <br /><br />For full details on how we handle your data, please see our <a href="/privacy">Privacy Policy</a>.
        </p>
      </div>

    </>
  );
}
